"use client";

import * as React from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useState, useEffect, useRef, useCallback } from "react";
import { Terminal, X } from "lucide-react";

interface HiddenTerminalProps {
  isOpen: boolean;
  onClose: () => void;
}

const TERMINAL_COMMANDS: Record<string, string | string[]> = {
  help: [
    "Available commands:",
    "  help     - Show this message",
    "  status   - Check system status",
    "  repair   - Attempt page repair",
    "  secret   - ???",
    "  clear    - Clear terminal",
    "  exit     - Close terminal",
  ],
  status: [
    "SYSTEM STATUS",
    "─────────────────────────",
    "Page Status: ERROR 404",
    "Memory: 73% utilized",
    "CPU: Nominal",
    "Network: Connected",
    "Glitch Level: CRITICAL",
    "─────────────────────────",
    "Recommendation: Try 'repair'",
  ],
  repair: [
    "Initiating repair sequence...",
    "Scanning page fragments... [OK]",
    "Reconstructing DOM tree... [OK]",
    "Restoring navigation... [OK]",
    "─────────────────────────",
    "Repair complete!",
    "Hint: Hover over the 404 to stabilize it.",
  ],
  secret: [
    "╔═══════════════════════════════╗",
    "║   You found the Easter egg!   ║",
    "║                               ║",
    "║   Built with love by the      ║",
    "║   development team.           ║",
    "║                               ║",
    "║   Keep exploring! :)          ║",
    "╚═══════════════════════════════╝",
  ],
  "404": ["I'm already a 404 page. That's meta."],
  hello: ["Hello, human. Welcome to the void."],
  hi: ["Hi there! Lost? Type 'help' for assistance."],
  whoami: ["You are a curious user exploring a 404 page."],
  ls: ["error_log.txt  fragments/  lost_page.bak  hope.exe"],
  cat: ["Meow? Wrong terminal, friend."],
  sudo: ["Nice try. No root access in the void."],
  hack: ["This isn't a movie. Type 'help' instead."],
  konami: [
    "↑ ↑ ↓ ↓ ← → ← → B A",
    "...Nice try, but wrong sequence!",
  ],
};

export function HiddenTerminal({ isOpen, onClose }: HiddenTerminalProps) {
  const [lines, setLines] = useState<Array<{ type: "input" | "output"; content: string }>>([
    { type: "output", content: "Welcome to the 404 Recovery Terminal" },
    { type: "output", content: 'Type "help" for available commands.' },
    { type: "output", content: "" },
  ]);
  const [currentInput, setCurrentInput] = useState("");
  const [commandHistory, setCommandHistory] = useState<string[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);
  const inputRef = useRef<HTMLInputElement>(null);
  const terminalRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    if (terminalRef.current) {
      terminalRef.current.scrollTop = terminalRef.current.scrollHeight;
    }
  }, [lines]);

  // Focus input when terminal opens
  useEffect(() => {
    if (isOpen && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isOpen]);

  const processCommand = useCallback((cmd: string) => {
    const trimmedCmd = cmd.trim().toLowerCase();

    // Add input to display
    setLines((prev) => [...prev, { type: "input", content: `> ${cmd}` }]);

    // Add to history
    if (trimmedCmd) {
      setCommandHistory((prev) => [...prev, trimmedCmd]);
    }
    setHistoryIndex(-1);

    // Process command
    if (trimmedCmd === "clear") {
      setLines([]);
      return;
    }

    if (trimmedCmd === "exit") {
      onClose();
      return;
    }

    const response = TERMINAL_COMMANDS[trimmedCmd];
    if (response) {
      const outputLines = Array.isArray(response) ? response : [response];
      // Add output with slight delay for effect
      outputLines.forEach((line, index) => {
        setTimeout(() => {
          setLines((prev) => [...prev, { type: "output", content: line }]);
        }, index * 50);
      });
    } else if (trimmedCmd) {
      setLines((prev) => [
        ...prev,
        { type: "output", content: `Command not found: ${trimmedCmd}` },
        { type: "output", content: 'Type "help" for available commands.' },
      ]);
    }
  }, [onClose]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      processCommand(currentInput);
      setCurrentInput("");
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      if (commandHistory.length > 0) {
        const newIndex = historyIndex === -1
          ? commandHistory.length - 1
          : Math.max(0, historyIndex - 1);
        setHistoryIndex(newIndex);
        setCurrentInput(commandHistory[newIndex]);
      }
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      if (historyIndex !== -1) {
        const newIndex = historyIndex + 1;
        if (newIndex >= commandHistory.length) {
          setHistoryIndex(-1);
          setCurrentInput("");
        } else {
          setHistoryIndex(newIndex);
          setCurrentInput(commandHistory[newIndex]);
        }
      }
    } else if (e.key === "Escape") {
      onClose();
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0, y: 20, scale: 0.95 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: 20, scale: 0.95 }}
          transition={{ duration: 0.2 }}
          className="fixed bottom-4 right-4 w-[500px] max-w-[calc(100vw-2rem)] z-50"
        >
          <div className="rounded-xl border border-[#B87333]/50 bg-black/95 backdrop-blur-xl shadow-2xl shadow-[#B87333]/20 overflow-hidden">
            {/* Terminal Header */}
            <div className="flex items-center justify-between px-4 py-2 bg-gradient-to-r from-[#B87333]/20 to-transparent border-b border-[#B87333]/30">
              <div className="flex items-center gap-2">
                <Terminal className="w-4 h-4 text-[#B87333]" />
                <span className="text-sm font-mono text-[#DA8A67]">
                  404-recovery-terminal
                </span>
              </div>
              <button
                onClick={onClose}
                className="p-1 rounded hover:bg-[#B87333]/20 transition-colors"
              >
                <X className="w-4 h-4 text-slate-400 hover:text-white" />
              </button>
            </div>

            {/* Terminal Body */}
            <div
              ref={terminalRef}
              className="h-[300px] overflow-y-auto p-4 font-mono text-sm scrollbar-thin"
              onClick={() => inputRef.current?.focus()}
            >
              {lines.map((line, index) => (
                <div
                  key={index}
                  className={`${
                    line.type === "input"
                      ? "text-[#DA8A67]"
                      : "text-slate-300"
                  } whitespace-pre-wrap`}
                >
                  {line.content}
                </div>
              ))}

              {/* Input Line */}
              <div className="flex items-center text-[#DA8A67]">
                <span className="mr-2">&gt;</span>
                <input
                  ref={inputRef}
                  type="text"
                  value={currentInput}
                  onChange={(e) => setCurrentInput(e.target.value)}
                  onKeyDown={handleKeyDown}
                  className="flex-1 bg-transparent outline-none text-[#DA8A67] caret-[#B87333]"
                  spellCheck={false}
                  autoComplete="off"
                />
                <motion.span
                  animate={{ opacity: [1, 0] }}
                  transition={{ duration: 0.5, repeat: Infinity, repeatType: "reverse" }}
                  className="w-2 h-4 bg-[#B87333] ml-0.5"
                />
              </div>
            </div>

            {/* Terminal Footer */}
            <div className="px-4 py-2 border-t border-[#B87333]/30 bg-slate-900/50">
              <p className="text-xs text-slate-500 font-mono">
                Press ESC to close | Ctrl+C to copy
              </p>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

// Hook to detect Konami code for opening the terminal
export function useKonamiCode(callback: () => void) {
  const konamiCode = [
    "ArrowUp",
    "ArrowUp",
    "ArrowDown",
    "ArrowDown",
    "ArrowLeft",
    "ArrowRight",
    "ArrowLeft",
    "ArrowRight",
    "KeyB",
    "KeyA",
  ];
  const [inputSequence, setInputSequence] = useState<string[]>([]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const newSequence = [...inputSequence, e.code].slice(-konamiCode.length);
      setInputSequence(newSequence);

      if (newSequence.join(",") === konamiCode.join(",")) {
        callback();
        setInputSequence([]);
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [inputSequence, callback]);
}

// Alternative trigger: triple-click detection
export function useTripleClick(callback: () => void) {
  const clickCountRef = useRef(0);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  const handleClick = useCallback(() => {
    clickCountRef.current += 1;

    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }

    if (clickCountRef.current >= 3) {
      callback();
      clickCountRef.current = 0;
    } else {
      timeoutRef.current = setTimeout(() => {
        clickCountRef.current = 0;
      }, 500);
    }
  }, [callback]);

  return handleClick;
}
